import{_ as t,o as a,c as e,aw as o}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"API","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/api/api.md","filePath":"wiki/dev-commit/network/network/api/api.md"}'),r={name:"wiki/dev-commit/network/network/api/api.md"};function n(l,i,p,s,_,c){return a(),e("div",null,[...i[0]||(i[0]=[o('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><ul><li><strong>API</strong> (Application Programming Interface, программный интерфейс приложения) - описание способов (набор классов, процедур, функций, структур или констант), которыми одна компьютерная программа может взаимодействовать с другой программой</li><li>API определяет функциональность, которую предоставляет программа (модуль, библиотека), при этом API позволяет абстрагироваться от того, как именно эта функциональность реализована</li><li>Программные компоненты взаимодействуют друг с другом посредством API. При этом обычно компоненты образуют иерархию — высокоуровневые компоненты используют API низкоуровневых компонентов, а те, в свою очередь, используют API ещё более низкоуровневых компонентов</li></ul><p>API библиотеки функций и классов включает в себя описание сигнатур функций и семантики функций</p><ul><li>Сигнатура функции - часть общего объявления функции, позволяющая средствам трансляции идентифицировать функцию среди других</li><li>Семантика функции - описание того, что данная функция делает. Семантика функции включает в себя описание того, что является результатом вычисления функции, как и от чего этот результат зависит</li></ul>',4)])])}const P=t(r,[["render",n]]);export{d as __pageData,P as default};
